"""
    Pack x, y, and z into fields of an 8-bit unsigned integer.
    x: bits 4..7 (4 bits)
    y: bits 2..3 (2 bits)
    z: bits 0..1 (2 bits)
    """
def pack(x: int, y: int, z: int) -> int {
    word = (x << 4) | (y << 2) | z;
    return word;
}

"""Parses nubase style spin information
        returns dictionary {value, extrapolated} """
def parse_isomer_spin(spin: Any) -> object {
    result = {};
    result['extrapolated'] = True if (spin.count('#') > 0) else False;
    if result['extrapolated'] {
        spin = spin.replace('#', ' ');
    }
    result['value'] = spin[0:8].strip();
    result['T'] = spin[8:].strip('T= ');
    return result;
}

