"""
    This is a utility that takes a dictionary and a list of keys
     and returns any keys with no value or missing from the dict.
    """
def get_unset_keys(dictionary: Any, keys: Any) -> object {
    return [
        k
        for k in keys
        if ((k not in dictionary) or not dictionary[k])
    ];
}

"""
    Minimum bolt spacing.

    :param d_0:
    :return:
    """
def bolt_min_dist(d_0: Any) -> object {
    e_1 = 1.2 * d_0;
    e_2 = 1.2 * d_0;
    e_3 = 1.5 * d_0;
    p_1 = 2.2 * d_0;
    p_2 = 2.4 * d_0;
    return (e_1, e_2, e_3, p_1, p_2);
}

"""Round down `x` to nearest `n`."""
def round_down(x: Any, n: Any) -> object {
    return ((x // n) * n);
}

"""
