"""
    Creates a map from stream name to stream size from the indices table.

    :param stream_indices:  The stream indices table.
    :return:                The map.
    """
def create_stream_size_map(stream_indices: Any) -> object {
    return {pair[0]: len(pair[1]) for pair in stream_indices};
}

"""The dataset supplied is scaled with the supplied scale. The scaled
    dataset is returned."""
def scale_yaxis(dataset: Any, scale: Any) -> object {
    result = {};
    result["data"] = [(x / scale["scale"]) for x in dataset];
    result["format"] = scale["label"];
    return result;
}

"""
    Check whether a rate limit is None or unlimited (indicated by '-1').

    :param rate_limit: the rate limit to check
    :return: bool
    """
def is_unlimited(rate_limit: Any) -> object {
    return ((rate_limit is None) or (rate_limit == -1));
}
